c = pymysql.connect(host="127.0.0.1", port=3306, user="root", password="433700",
                    database="resaname_kb_final_inspect", charset="utf8mb4")
cur = c.cursor()

def wc(p):
    t = 0
    for k in WORDS_KEYS:
        v = p.get(k)
        if isinstance(v, str):
            t += len(v.split())
        elif isinstance(v, list):
            for x in v:
                t += len(str(x).split())
    return t

count = 0
for code, extra in ADD.items():
    cur.execute("SELECT id, properties, version FROM kb_entities WHERE code=%s", (code,))
    eid, props, ver = cur.fetchone()
    p = json.loads(props)
    before = wc(p)
    if before >= 500:
        print(code, "already >=500 (w=%d), skip" % before)
        continue
    if not isinstance(p.get("evolution"), str):
        p["evolution"] = ""
    sentinel = " ".join(extra.split()[-4:])
    if sentinel in p["evolution"]:
        print(code, "already padded, skip")
        continue
    p["evolution"] = (p["evolution"] + " " + extra).strip()
    after = wc(p)
    newprops = json.dumps(p, ensure_ascii=False)
    nv = ver + 1
    cur.execute("UPDATE kb_entities SET properties=%s, version=%s, updated_at=%s, updated_by=%s WHERE id=%s",
                (newprops, nv, NOW, STAMP, eid))
    cur.execute("INSERT INTO kb_entity_versions (entity_id, version, snapshot, change_reason, changed_by, created_at) "
                "VALUES (%s,%s,%s,%s,%s,%s)", (eid, nv, newprops, "pad to >=500 words (pass3)", STAMP, NOW))
    cur.execute("INSERT INTO kb_audit_log (entity_code, action, detail, source, created_at) VALUES (%s,%s,%s,%s,%s)",
                (code, "pad_evolution",
                 json.dumps({"before_words": before, "after_words": after}, ensure_ascii=False), STAMP, NOW))
    count += 1
    print(code, "w: %d -> %d" % (before, after), "OK" if after >= 500 else "STILL SHORT")
    if count % 5 == 0:
        c.commit()
        print("  [committed %d]" % count)
c.commit()
c.close()
print("DONE pass3, applied", count)
